unordered_set<Multiset,MH> build_reps(){vector<long long>exp={1,1,4,14,61,268,1283,6032,27763};unordered_set<Multiset,MH>reps;Multiset e;reps.insert(e);for(int sz=1;sz<=8;sz++){unordered_set<Multiset,MH>n;n.reserve(reps.size()*8);for(auto&ms:reps){int mult[35]={};for(int i=0;i<ms.n;i++)mult[ms.a[i]]++;for(int s=0;s<35;s++)if(mult[s]<3){Multiset x=ms;x.a[x.n++]=s;sort(x.a.begin(),x.a.begin()+x.n);n.insert(canon(x));}}reps.swap(n);if((long long)reps.size()!=exp[sz])throw 12;}return reps;}
vector<pair<uint16_t,uint16_t>> build_pairsets(){vector<pair<uint16_t,uint16_t>>ps;for(int a=0;a<8;a++)for(int b=a+1;b<8;b++)for(int c=0;c<8;c++)if(c!=a&&c!=b)for(int d=c+1;d<8;d++)if(d!=a&&d!=b){uint16_t m1=(1u<<a)|(1u<<b),m2=(1u<<c)|(1u<<d);if(m1<m2)ps.push_back({m1,m2});}sort(ps.begin(),ps.end());ps.erase(unique(ps.begin(),ps.end()),ps.end());if(ps.size()!=210)throw 13;return ps;}
